service.method:

SELECT
	DEPT
FROM
	SDEPT
WHERE
		HOUSE_CODE 		= ${session.HOUSE_CODE}
	AND COMPANY_CODE 	= ${session.COMPANY_CODE}	
	AND DEPT 			= ${DEPTCODE}


UPDATE SDEPT
	SET
		  DEPT_NAME_LOC	  = ${DEPT_NAME_LOC}
		, PARENT_DEPT	  = ${PARENT_DEPT}
		, MANAGER_ID	  = ${MANAGER_ID}  
		, DEL_FLAG		  = ${DEL_FLAG}
		, CHANGE_DATE     = ${current.DATE}
		, CHANGE_TIME     = ${current.TIME}
		, CHANGE_USER_ID  = ${session.ID}
WHERE
		HOUSE_CODE        = ${session.HOUSE_CODE}
		AND COMPANY_CODE  = ${session.COMPANY_CODE}
		AND DEPT		  = ${DEPT}


INSERT INTO SDEPT
	(
		  HOUSE_CODE
		, COMPANY_CODE
		, DEPT
		, DEPT_NAME_LOC
		, MANAGER_ID
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID				
		, PARENT_DEPT
		, DEL_FLAG
	)
	VALUES
	(
		  ${session.HOUSE_CODE}
		, ${session.COMPANY_CODE}
		, ${DEPT}
		, ${DEPT_NAME_LOC}
		, ${MANAGER_ID}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}				
		, ${PARENT_DEPT}
		, ${DEL_FLAG}
	)
